changeSet.sql:
ALTER TABLE books ADD COLUMN cover_title VARCHAR(255);
UPDATE books SET cover_title=name;
ALTER TABLE books ADD COLUMN retired_title TEXT;
ALTER TABLE books ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE books ADD COLUMN management_revision BIGINT NOT NULL DEFAULT 0;
ALTER TABLE java_library DROP CONSTRAINT library_section_valid;
ALTER TABLE java_library ADD COLUMN custom_cover BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE store_sections (
 id VARCHAR(80) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE,
 catalog_key VARCHAR(255) NOT NULL UNIQUE, library_key VARCHAR(32) NOT NULL UNIQUE,
 sort_order INTEGER NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0
);
INSERT INTO store_sections(id,name,catalog_key,library_key,sort_order) VALUES
 ('java','Java','Java','java',60),('civil-law','Гражданское право','Гражданское право','civil-law',50),('ai','AI','AI','ai',70);
INSERT INTO store_sections(id,name,catalog_key,library_key,sort_order)
 SELECT 'catalog-' || CAST(MIN(id) AS VARCHAR),CASE WHEN LENGTH(category)>80 THEN SUBSTRING(category,1,60) || ' [' || CAST(MIN(id) AS VARCHAR) || ']' ELSE category END,category,CAST(MIN(id) AS VARCHAR) || '-catalog',10
 FROM books WHERE category IS NOT NULL AND TRIM(category)<>'' AND category NOT IN ('Java','Гражданское право','AI') GROUP BY category;
INSERT INTO store_sections(id,name,catalog_key,library_key,sort_order) SELECT 'uncategorized','Каталог','Каталог','uncategorized',100 WHERE NOT EXISTS(SELECT 1 FROM store_sections WHERE catalog_key='Каталог');
UPDATE books SET category='Каталог' WHERE category IS NULL OR TRIM(category)='';
CREATE TABLE catalogue_state(id INTEGER PRIMARY KEY CHECK(id=1));
INSERT INTO catalogue_state(id) VALUES(1);
CREATE TABLE catalog_pdf (
 book_id BIGINT PRIMARY KEY REFERENCES books(id),
 library_id VARCHAR(36) NOT NULL UNIQUE REFERENCES java_library(id) ON DELETE CASCADE
);
CREATE TABLE catalog_covers (
 book_id BIGINT PRIMARY KEY REFERENCES books(id), data BYTEA NOT NULL
);
